import {
  createOpenAICompatible,
  type OpenAICompatibleProviderSettings,
} from '@ai-sdk/openai-compatible';

/**
 * LlamaGate provider settings
 */
export interface LlamaGateProviderSettings
  extends Omit<OpenAICompatibleProviderSettings, 'name' | 'baseURL'> {
  /**
   * LlamaGate API key. Defaults to LLAMAGATE_API_KEY environment variable.
   */
  apiKey?: string;
  /**
   * Base URL for LlamaGate API. Defaults to https://api.llamagate.dev/v1
   */
  baseURL?: string;
}

/**
 * LlamaGate provider instance type
 */
export interface LlamaGateProvider {
  /**
   * Creates a chat model for text generation.
   * @param modelId - The model ID (e.g., 'llama-3.1-8b', 'qwen3-8b')
   */
  (modelId: LlamaGateChatModelId, settings?: LlamaGateProviderSettings): ReturnType<
    ReturnType<typeof createOpenAICompatible>
  >;

  /**
   * Creates a chat model for text generation.
   * @param modelId - The model ID (e.g., 'llama-3.1-8b', 'qwen3-8b')
   */
  chatModel(
    modelId: LlamaGateChatModelId,
    settings?: LlamaGateProviderSettings
  ): ReturnType<ReturnType<typeof createOpenAICompatible>['chatModel']>;

  /**
   * Creates an embedding model.
   * @param modelId - The embedding model ID (e.g., 'nomic-embed-text')
   */
  textEmbeddingModel(
    modelId: LlamaGateEmbeddingModelId,
    settings?: LlamaGateProviderSettings
  ): ReturnType<ReturnType<typeof createOpenAICompatible>['textEmbeddingModel']>;
}

/**
 * Available LlamaGate chat model IDs
 */
export type LlamaGateChatModelId =
  // Tool calling
  | 'functiongemma'
  // Small general purpose (3-4B)
  | 'granite4-3b'
  | 'llama-3.2-3b'
  | 'gemma3-4b'
  // Code models
  | 'deepseek-coder-6.7b'
  | 'codellama-7b'
  | 'codegemma-7b'
  | 'starcoder2-7b'
  | 'rnj-1-8b'
  | 'qwen2.5-coder-7b'
  // General purpose (7-8B)
  | 'olmo-3-7b'
  | 'qwen3-8b'
  | 'dolphin3-8b'
  | 'llama-3.1-8b'
  | 'mistral-7b-v0.3'
  // Reasoning models
  | 'openthinker-7b'
  | 'deepseek-r1-8b'
  | 'deepseek-r1-7b-qwen'
  // Vision models
  | 'qwen3-vl-8b'
  | 'llava-7b'
  | 'olmocr-7b'
  | 'ui-tars-7b'
  // Large models
  | 'gpt-oss-20b'
  // Allow any string for flexibility
  | (string & {});

/**
 * Available LlamaGate embedding model IDs
 */
export type LlamaGateEmbeddingModelId =
  | 'nomic-embed-text'
  | 'embeddinggemma-300m'
  | 'qwen3-embedding-8b'
  // Allow any string for flexibility
  | (string & {});

/**
 * Creates a LlamaGate provider instance.
 *
 * @param options - Provider configuration options
 * @returns A LlamaGate provider instance
 *
 * @example
 * ```ts
 * import { createLlamaGate } from '@llamagate/ai-sdk-provider';
 *
 * const llamagate = createLlamaGate({
 *   apiKey: 'your-api-key', // or set LLAMAGATE_API_KEY env var
 * });
 *
 * const { text } = await generateText({
 *   model: llamagate('llama-3.1-8b'),
 *   prompt: 'Hello, world!',
 * });
 * ```
 */
export function createLlamaGate(
  options: LlamaGateProviderSettings = {}
): LlamaGateProvider {
  const baseURL = options.baseURL ?? 'https://api.llamagate.dev/v1';
  const apiKey = options.apiKey ?? process.env.LLAMAGATE_API_KEY;

  const provider = createOpenAICompatible({
    name: 'llamagate',
    baseURL,
    apiKey,
    headers: options.headers,
    fetch: options.fetch,
  });

  const llamagateProvider = function (
    modelId: LlamaGateChatModelId,
    settings?: LlamaGateProviderSettings
  ) {
    return provider.chatModel(modelId, settings as any);
  } as LlamaGateProvider;

  llamagateProvider.chatModel = (
    modelId: LlamaGateChatModelId,
    settings?: LlamaGateProviderSettings
  ) => {
    return provider.chatModel(modelId, settings as any);
  };

  llamagateProvider.textEmbeddingModel = (
    modelId: LlamaGateEmbeddingModelId,
    settings?: LlamaGateProviderSettings
  ) => {
    return provider.textEmbeddingModel(modelId, settings as any);
  };

  return llamagateProvider;
}

/**
 * Default LlamaGate provider instance.
 * Uses LLAMAGATE_API_KEY environment variable for authentication.
 *
 * @example
 * ```ts
 * import { llamagate } from '@llamagate/ai-sdk-provider';
 *
 * const { text } = await generateText({
 *   model: llamagate('llama-3.1-8b'),
 *   prompt: 'Hello, world!',
 * });
 * ```
 */
export const llamagate = createLlamaGate();
